/* One client-owned total budget; no attendance-fee or additional-spend fields. */
function initialiseSimpleCallout(j,budget,authorised){j.callout={budgetMode:'total',totalBudget:authorised?budget:null,status:authorised?'Approved':'Pending',actualTotal:null,repairAuthorised:authorised,approvedAt:authorised?now():null,overrun:null,scope:'Call-out work within the client-authorised total budget.'};j.opsAction='callout';j.reviewedAt=now();j.assigned=true;if(j.team==='Unassigned')j.team='Sevlink Repairs Team';j.status=authorised?'Awaiting schedule':'Awaiting approval'}
const normaliseBeforeSimpleCallout=normalise;normalise=function(){normaliseBeforeSimpleCallout();for(const j of state.jobs){if(j.callout&&j.callout.budgetMode!=='total'){const c=j.callout;j.callout={...c,budgetMode:'total',totalBudget:c.status==='Approved'?Number(c.fee||0)+Number(c.budget||0):null,actualTotal:c.actual==null?null:Number(c.fee||0)+Number(c.actual),repairAuthorised:c.status==='Approved',overrun:null};delete j.callout.fee;delete j.callout.budget;delete j.callout.actual}}};
function calloutBudgetPanel(j){const c=j.callout;if(!c)return '';return `<div class="notice"><b>Call-out · ${c.overrun?.status==='Pending'?'additional approval required':c.status==='Approved'?'budget authorised':'awaiting client budget'}</b>${role!=='tenant'?`<p>Maximum total budget: <b>${c.totalBudget==null?'Awaiting agency':money(c.totalBudget)}</b>${c.actualTotal!=null?'<br>Recorded total cost: '+money(c.actualTotal):''}</p>`:''}${c.overrun?.status==='Pending'?`<p>Further work needs approval before proceeding.${role!=='tenant'?'<br>Proposed total: '+money(c.overrun.total):''}</p>`:''}${role==='manager'&&c.status==='Pending'?`<button class="primary" onclick="authoriseCallout('${j.id}')">Set maximum budget & book call-out</button>`:''}${role==='manager'&&c.overrun?.status==='Pending'?`<button class="primary" onclick="overrunApprovalForm('${j.id}')">Review extra approval</button>`:''}<p style="margin-bottom:0">Work within the authorised budget goes to invoicing after completion.</p></div>`}
calloutForm=function(jid){const j=getJob(jid);if(!j)return;if(role==='manager'){authoriseCallout(jid);return}if(role!=='sevlink'||!['new','callouts','assessment'].includes(jobStage(j)))return;openForm('Request a client call-out budget.',`<p>The agency sets the maximum total budget. Sevlink does not set this amount.</p><label>Short message to the client</label><textarea name="message" rows="3" required maxlength="1500">Please set the maximum total budget to authorise this call-out.</textarea>`,'Request client budget',async d=>{if(await requestCallout(jid,d.get('message'))){render();jobDetail(jid);toast('Client budget requested.')}})};
requestCallout=async function(jid,message='Please authorise a maximum total call-out budget.'){const j=getJob(jid);if(!j||role!=='sevlink'||!['new','callouts','assessment'].includes(jobStage(j)))return false;return commit(()=>{initialiseSimpleCallout(j,null,false);addEvent(j,'Call-out budget requested',String(message));notify(j,'Call-out budget requested',j.ref+': please set your maximum total budget.')})};
authoriseCallout=function(jid){const j=getJob(jid);if(!j||role!=='manager'||(j.callout&&j.callout.status!=='Pending'))return;openForm('Book a call-out.',`<p>${esc(property(j.property)?.name)}<br>${esc(j.title)}</p><label>Maximum total call-out budget (ZAR)</label><input name="totalBudget" type="number" required min="0.01" max="10000000" step="0.01"><div class="notice">Sevlink can carry out work within this total. Any amount above it requires your further approval before proceeding.</div>`,'Authorise budget & book',async d=>{if(await approveCallout(jid,Number(d.get('totalBudget')))){render();jobDetail(jid,'schedule');toast('Call-out booked. Ready to arrange attendance.')}})};
approveCallout=async function(jid,totalBudget){const j=getJob(jid);if(!j||role!=='manager'||(j.callout&&j.callout.status!=='Pending')||!Number.isFinite(totalBudget)||totalBudget<=0)return false;return commit(()=>{initialiseSimpleCallout(j,totalBudget,true);addEvent(j,'Call-out budget authorised','Maximum total '+money(totalBudget),'financial');notify(j,'Call-out booked',j.ref+': budget authorised; arrange attendance.')})};
const stageBeforeSimpleCallout=jobStage;jobStage=function(j){if(j.callout?.overrun?.status==='Pending')return 'approval';return stageBeforeSimpleCallout(j)};
const actionBeforeSimpleCallout=nextAction;nextAction=function(j){if(j.callout?.overrun?.status==='Pending')return 'Await client approval for the proposed total';if(j.callout&&jobStage(j)==='underway')return 'Complete within budget and invoice';if(j.callout&&jobStage(j)==='approval'&&j.callout.status==='Pending')return 'Client sets maximum total call-out budget';if(jobStage(j)==='callouts')return 'Request the client’s total budget';return actionBeforeSimpleCallout(j)};
findingsForm=function(jid){simpleCalloutCompletion(jid)};
function simpleCalloutCompletion(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!j.callout||!['Scheduled','In progress'].includes(j.status))return;if(j.callout.overrun?.status==='Pending'){toast('Client approval is required before proceeding above the budget.');return}openForm('Complete call-out or request approval.',`<div class="notice">Client maximum total budget: <b>${money(j.callout.totalBudget)}</b></div><label>Total call-out cost (ZAR)</label><input name="total" type="number" required min="0" max="10000000" step="0.01" value="${j.callout.overrun?.total??j.callout.actualTotal??''}"><label>Work carried out / further work needed</label><textarea name="notes" rows="4" required maxlength="2500">${esc(j.callout.overrun?.notes||'')}</textarea><label>Checks / recommendations (optional)</label><textarea name="checks" rows="2" maxlength="1500"></textarea><label>Completion / findings photo (optional)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><div class="notice">Within budget: complete and upload the invoice.<br>Above budget: request client approval before doing the extra work.</div>`,'Save total & continue',async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}const result=await finishSimpleCallout(jid,Number(d.get('total')),d.get('notes'),d.get('checks'),photo);if(!result)return;render();if(result==='approval'){jobDetail(jid);toast('Extra approval requested. No completion or invoice recorded.')}else{invoiceForm(jid);toast('Call-out completed. Upload the invoice.')}})}
async function finishSimpleCallout(jid,total,notes,checks='',photo=null){const j=getJob(jid);if(!j||role!=='sevlink'||j.callout?.status!=='Approved'||j.callout.overrun?.status==='Pending'||!['Scheduled','In progress'].includes(j.status)||!Number.isFinite(total)||total<0||!notes?.trim())return false;const over=total>j.callout.totalBudget;const ok=await commit(()=>{if(over){j.callout.overrun={status:'Pending',total,notes,requestedAt:now(),previousStatus:j.status};addEvent(j,'Additional call-out approval requested','Proposed total '+money(total)+' exceeds the authorised total '+money(j.callout.totalBudget),'financial');notify(j,'Call-out approval needed',j.ref+': please review the proposed total before further work.')}else{j.callout.actualTotal=total;j.callout.findings=notes;j.status='Completed';j.completedAt=now();j.completionNotes=notes;j.completionChecks=checks||'Completion recorded by Sevlink.';if(photo){photo.phase='after';photo.at=now();j.photos.push(photo);j.afterPhotos.push(photo)}addEvent(j,'Call-out completed','Completed within the client-authorised budget.');addEvent(j,'Call-out total recorded',money(total),'financial');j.history.push('Call-out completed; ready to invoice.')}});return ok?(over?'approval':'invoice'):false}
function overrunApprovalForm(jid){const j=getJob(jid);if(!j||role!=='manager'||j.callout?.overrun?.status!=='Pending')return;const o=j.callout.overrun;openForm('Review additional call-out approval.',`<p>${esc(o.notes)}</p><div class="notice">Current maximum: ${money(j.callout.totalBudget)}<br>Proposed new total: <b>${money(o.total)}</b><br>This replaces the previous limit; it is not added on top.</div><label>Decision</label><select name="decision"><option value="approve">Approve the proposed new total</option><option value="decline">Decline further spending</option></select><label>Comment (optional)</label><textarea name="note" rows="2" maxlength="1000"></textarea>`,'Save decision',async d=>{if(await decideCalloutOverrun(jid,d.get('decision')==='approve',d.get('note'))){render();jobDetail(jid);toast('Decision recorded.')}})}
async function decideCalloutOverrun(jid,accept,note=''){const j=getJob(jid);if(!j||role!=='manager'||j.callout?.overrun?.status!=='Pending')return false;return commit(()=>{const o=j.callout.overrun;o.status=accept?'Approved':'Declined';o.decidedAt=now();o.note=note;if(accept)j.callout.totalBudget=o.total;addEvent(j,'Call-out extra approval '+(accept?'approved':'declined'),(accept?'Maximum total now '+money(o.total):'No additional spending authorised.')+(note?' '+note:''),'financial');notify(j,'Call-out decision',j.ref+': extra approval '+(accept?'approved':'declined')+'.')})}
const completionBeforeSimpleCallout=completionForm;completionForm=function(jid){const j=getJob(jid);return j?.callout?simpleCalloutCompletion(jid):completionBeforeSimpleCallout(jid)};
const invoiceBeforeSimpleCallout=invoiceForm;invoiceForm=function(jid){const j=getJob(jid);if(j?.callout&&(j.status!=='Completed'||j.callout.overrun?.status==='Pending')){toast('Complete the call-out within the approved budget before invoicing.');return}invoiceBeforeSimpleCallout(jid);if(role==='sevlink'&&j?.callout&&modal.open){const amount=modal.querySelector('input[name="amount"]');if(amount){amount.value=j.callout.actualTotal??'';amount.min='0'}const form=$('#form'),submit=form.onsubmit;form.onsubmit=async e=>{const total=Number(new FormData(form).get('amount')),existing=(j.invoices||[]).reduce((n,i)=>n+i.amount,0);if(!Number.isFinite(total)||existing+total>j.callout.totalBudget){e.preventDefault();toast('The total invoiced cannot exceed the client-authorised budget. Request further approval first.');return}return submit(e)}}};
const approvedBeforeSimpleCallout=approved;approved=function(j){return j.callout?j.callout.status==='Approved':approvedBeforeSimpleCallout(j)};
const quotesBeforeSimpleCallout=renderQuotes;renderQuotes=function(j){if(j.callout){$('#jobcontent').innerHTML='<div class="notice">This call-out uses a client-authorised total budget. Extra approval is requested only if the total needs to exceed that budget.</div>';return}return quotesBeforeSimpleCallout(j)};
const detailBeforeSimpleCallout=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeSimpleCallout(jid,section);const j=getJob(jid);if(j?.callout){const quotes=modal.querySelector('[data-tab="quotes"]');if(quotes)quotes.remove()}if(j&&role==='manager'&&!j.callout&&!['Completed','Scheduled','In progress','Awaiting approval'].includes(j.status))$('#jobcontent').insertAdjacentHTML('beforeend',`<div class="actions"><button class="secondary" onclick="authoriseCallout('${jid}')">Book a call-out with my maximum budget</button></div>`)};
